import { connectNoir, restoreNoir, disconnectNoir, observeNoir } from './wallet.js';

const items = [
 {id:17,art:0,price:.42,rank:128,head:'Hood',mask:'Skull',color:'Olive'},
 {id:208,art:1,price:.48,rank:63,head:'Cap',mask:'Visor',color:'Charcoal'},
 {id:1042,art:2,price:.55,rank:209,head:'Hood',mask:'Respirator',color:'Moss'},
 {id:333,art:3,price:.62,rank:87,head:'Hood',mask:'Bandana',color:'Rust'},
 {id:2601,art:4,price:.73,rank:34,head:'Helmet',mask:'Visor',color:'Navy'},
 {id:3190,art:5,price:.85,rank:156,head:'Hood',mask:'Bandana',color:'Plum'}
];
const tabs=[['for-sale','For sale'],['bids','Bids'],['sales','Sales'],['traits','Traits'],['explorer','Explorer'],['activity','Activity']];
const main=document.querySelector('main');
let connection=null,activeTrait='',search='',sort='price-low';
const money=n=>n.toFixed(2);
const art=(i,extra='')=>`<div class="portrait ${extra}" role="img" aria-label="Zc concept portrait, ${items[i].color.toLowerCase()} ${items[i].head.toLowerCase()}" style="--x:${(i%3)*50}%;--y:${Math.floor(i/3)*100}%" data-number="#${String(items[i].id).padStart(4,'0')}"></div>`;
const card=i=>`<button class="nft-card" data-item="${i.id}" aria-label="View Zc #${String(i.id).padStart(4,'0')}">${art(i.art)}<span class="card-top"><span class="card-title">Zc #${String(i.id).padStart(4,'0')}</span><span class="rank">DEMO</span></span><span class="card-bottom"><span>Example asking price</span><span class="price">${money(i.price)} ZEC</span></span></button>`;
const notice='<div class="demo-notice">Collection preview · Artwork, listings and activity are examples. Live trading is not open.</div>';
const stats=()=>`<div class="stats"><div class="stat"><div class="stat-label">Floor price</div><div class="stat-value">0.42<span>ZEC</span></div><div class="stat-note">Example floor</div></div><div class="stat"><div class="stat-label">Total volume</div><div class="stat-value">128.64<span>ZEC</span></div><div class="stat-note">Example all-time volume</div></div><div class="stat"><div class="stat-label">For sale</div><div class="stat-value">6<span>items</span></div><div class="stat-note">Preview listings</div></div><div class="stat"><div class="stat-label">Collection size</div><div class="stat-value">3,333<span>NFTs</span></div><div class="stat-note">Planned total supply</div></div></div>`;
const tabbar=selected=>`<nav class="tab-bar" aria-label="Marketplace sections">${tabs.map(([slug,label])=>`<a href="#/${slug}" ${slug===selected?'aria-current="page"':''} class="${slug===selected?'selected':''}">${label}${slug==='for-sale'?'<span class="tab-count">6</span>':''}</a>`).join('')}</nav>`;
const steps=()=>`<section class="editorial" id="how-to-trade"><div class="editorial-intro"><div class="eyebrow">A FEW SIMPLE STEPS</div><h2 style="margin-top:16px">How to trade</h2><p>Your collection. Your wallet.<br>Start with Noir, explore Zc.</p></div><div class="steps"><div class="step"><span class="step-number">01 /</span><div><h3>Get your wallet ready.</h3><p>Install the <a href="https://www.zknoir.com/" target="_blank" rel="noopener noreferrer">Noir Wallet extension</a>, create or import your wallet, and keep your recovery phrase somewhere safe.</p></div></div><div class="step"><span class="step-number">02 /</span><div><h3>Connect. Find your identity.</h3><p>Select Sign in, approve the connection in Noir, then explore the collection and its traits.</p></div></div><div class="step"><span class="step-number">03 /</span><div><h3>Trade when the market opens.</h3><p>Live buying, bids and listings will open after the collection is connected. This preview does not accept payments or transfer NFTs.</p></div></div></div></section>`;
const faq=()=>`<section class="editorial" id="faq"><div class="editorial-intro"><div class="eyebrow">GOOD TO KNOW</div><h2 style="margin-top:16px">FAQ</h2><p>A little clarity.<br>A lot of privacy.</p></div><div class="faq-list">${[
 ['What is Zc?','Zc is a planned collection of 3,333 digital identities on Zcash. Each character explores the space between individuality and anonymity through pixel art. The artwork shown here is concept artwork for the site preview.'],
 ['How many NFTs are in the collection?','The planned collection contains 3,333 NFTs. The six pieces currently displayed are examples, not the complete issued collection.'],
 ['Which wallet do I need?','Use the Noir Wallet browser extension. Select Sign in for the official download link, then unlock Noir and approve the connection. On mobile, use a browser that supports the extension or continue on desktop.'],
 ['Can I buy, sell or place a bid now?','Not yet. You can explore this preview and connect Noir. Live orders and NFT transfers will become available after the collection metadata and trading service are connected.'],
 ['What currency and fees will the market use?','Prices are displayed in ZEC. Any marketplace fees, royalties and network costs must be shown before a live order can be confirmed. No payment is requested in this preview.'],
 ['Does connecting give the site access to my funds?','Connecting requests access to the accounts you authorize in Noir. It is not a payment approval. This preview never requests a transaction or a recovery phrase. You can revoke the connection in Noir or disconnect here.']
 ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>`;

function home(){return `<section class="hero"><div><div class="eyebrow"><span class="badge">ON ZCASH</span> INDEPENDENT BY DESIGN</div><h1>Zc<span>/ 3333</span></h1><p class="hero-sub">An identity. Not an exposure.</p></div><div class="hero-copy"><p><strong>3,333 characters. A shared instinct for privacy.</strong><br>A collection of digital identities at the edge of the visible. Distinct in every pixel. Connected by Zcash.</p><div class="hero-actions"><a class="button" href="#/for-sale">Explore the collection <span>↗</span></a><a class="text-link" href="#/how-to-trade">How to trade <span>↘</span></a></div></div></section><div class="art-strip">${items.map((i)=>art(i.art)).join('')}</div><div class="art-caption"><span>Six identities from the concept collection.</span><span>3,333 PIECES / ZCASH NETWORK</span></div><section id="market"><div class="section-heading"><h2>The market <small>Find your Zc.</small></h2><span class="preview-label">Demo market data</span></div>${stats()}${tabbar('for-sale')}<div class="toolbar"><span class="toolbar-label">A first look at the collection</span><a class="text-link" href="#/for-sale">View all listings <span>↗</span></a></div><div class="nft-grid">${items.slice(0,4).map(card).join('')}</div><div class="market-bottom"><a class="button secondary" href="#/explorer">Explore all identities <span>↗</span></a></div></section>${steps()}${faq()}`;}

function table(kind){const bids=kind==='bids';return `<div class="table-wrap"><table><thead><tr><th>Item</th><th>${bids?'Top bid':'Event'}</th><th>${bids?'Example bidder':'Example amount'}</th><th>${bids?'Status':'Time'}</th><th></th></tr></thead><tbody>${items.slice(0,kind==='activity'?6:4).map((i,n)=>`<tr><td><button class="table-link table-nft" data-item="${i.id}">${art(i.art)}<span>Zc #${String(i.id).padStart(4,'0')}</span></button></td><td class="event-type">${bids?`${money(i.price-.1)} ZEC`:kind==='sales'?'Sale':['Listing','Bid','Sale'][n%3]}</td><td>${bids?`Demo collector ${n+1}`:`${money(i.price)} ZEC`}</td><td>${bids?'Preview only':`${n*3+2}h ago · demo`}</td><td><button class="text-button" data-item="${i.id}">View ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function traits(){return `<div class="traits-grid">${[['Headwear','head'],['Face covering','mask'],['Palette','color']].map(([label,key])=>`<section class="trait-group"><h3>${label}</h3>${[...new Set(items.map(i=>i[key]))].map(v=>`<button class="trait-item" data-trait="${v}"><span>${v}</span><span>${items.filter(i=>i[key]===v).length} / 6 samples ↗</span></button>`).join('')}</section>`).join('')}</div>`;}
function marketplace(route){const label=tabs.find(([s])=>s===route)?.[1]||'For sale';return `<section class="page-market"><div class="page-top"><div class="eyebrow">ZC / THE MARKETPLACE</div><h1>${label}</h1><p>${({traits:'The details make the identity. Explore the traits in the concept collection.',explorer:'Find your identity among the collection previews.',bids:'A look at how offers will appear in the Zc market.',sales:'The sales ledger, from first trade to latest collector.',activity:'Listings, bids and sales in one place.'})[route]||'A collection of characters. A world of possibilities.'}</p></div>${notice}${route==='for-sale'?stats():''}${tabbar(route)}<div class="toolbar"><span id="result-count" class="toolbar-label">${route==='traits'?'Traits from 6 concept NFTs':route==='explorer'?'6 previews · 3,333 planned':route==='activity'?'Example collection activity':'Example market records'}</span>${['for-sale','explorer'].includes(route)?`<div class="filters"><label class="sr-only" for="search">Search NFT ID or trait</label><input id="search" placeholder="Search ID or trait" value=""><label class="sr-only" for="sort">Sort items</label><select id="sort"><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="id">ID: low to high</option></select></div>`:route==='activity'?'<label>Event <select id="event-filter"><option value="all">All events</option><option>Listing</option><option>Bid</option><option>Sale</option></select></label>':''}</div>${activeTrait&&route==='explorer'?`<button class="button secondary" id="clear-trait">Clear trait filter: ${activeTrait} ×</button><br><br>`:''}<div id="market-content">${route==='traits'?traits():['for-sale','explorer'].includes(route)?'<div class="nft-grid" id="results"></div>':table(route)}</div></section>`;}

function terms(){return `<article class="terms"><div class="eyebrow">ZC / LEGAL</div><h1>Terms of use</h1><p>Preview edition · 20 September 2026</p><div class="demo-notice" style="margin-top:25px">Draft terms for this preview. Operator details, collection rights and final trading terms must be completed before the marketplace opens.</div><h2>1. This website</h2><p>Zc presents a planned collection of 3,333 digital collectibles on Zcash. This version is an interactive preview. Its artwork, prices, bids, sales and activity are illustrative and are not live offers, evidence of ownership or verified blockchain records.</p><h2>2. Wallet connection</h2><p>You may connect accounts through the independent Noir Wallet extension. Connection requests are approved in your wallet. We do not ask for recovery phrases or private keys. A wallet connection is not proof of NFT ownership, a completed purchase, or a server-authenticated trading session.</p><h2>3. No live transactions in this preview</h2><p>This version does not accept orders or payments, reserve items, execute trades, or transfer NFTs. Do not send funds based on example listings. Before live trading, the site must identify the collection, settlement mechanism, operator, applicable fees and support process.</p><h2>4. Future trades and network risks</h2><p>Once trading is enabled under updated terms, review the asset, recipient, price and fees before approving any transaction. Blockchain transfers may be irreversible. Network delays, service outages, technical defects and loss of wallet access can affect your ability to trade. Collectibles may lose all value and do not promise returns.</p><h2>5. Artwork and collectible rights</h2><p>Preview images are concept artwork. Browsing this site does not grant intellectual property rights in them. Ownership of a future collectible will not automatically transfer copyright. The applicable license and permitted uses must be published with the final collection.</p><h2>6. Acceptable use</h2><p>Do not use the site to deceive others, misrepresent ownership, interfere with its operation, exploit vulnerabilities, or violate applicable law. You are responsible for protecting your wallet and reviewing the requests you approve.</p><h2>7. Privacy and third-party services</h2><p>This preview does not store connected wallet addresses in browser storage or send them to a marketplace server. Hosting providers may process standard connection logs. Google Fonts receives ordinary asset requests. Noir and its extension store operate under their own terms and privacy policies. The site does not guarantee anonymity.</p><h2>8. Availability and responsibility</h2><p>The preview may change or become unavailable. Information may be incomplete or incorrect. Nothing on the site is investment, tax or legal advice. Nothing in these terms excludes rights or responsibilities that cannot be excluded by applicable law.</p><h2>9. Before launch</h2><p>The operator's legal identity, contact details, governing law, dispute process, final privacy notice, collectible license and trading fees remain to be specified. Revised terms must be made available before users can enter a live trade.</p><a href="#/" class="button secondary" style="margin-top:32px">Back to collection ↗</a></article>`;}

function render(){const route=location.hash.replace(/^#\/?/,'')||'home';search='';sort='price-low';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(tabs.some(([s])=>s===route)?'market':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});main.innerHTML=['home','how-to-trade','faq'].includes(route)?home():route==='terms'?terms():tabs.some(([s])=>s===route)?marketplace(route):'<section class="empty"><h1>Page not found</h1><p><a href="#/">Return to the collection</a></p></section>';document.title=`${route==='home'?'Zc — 3,333 identities on Zcash':`${tabs.find(([s])=>s===route)?.[1]||route.replaceAll('-',' ')} · Zc`}`;if(document.querySelector('#results'))filterItems();if(['faq','how-to-trade'].includes(route))document.getElementById(route).scrollIntoView();else window.scrollTo(0,0);}
function filterItems(){const query=search.trim().toLowerCase();let list=items.filter(i=>`${i.id} ${String(i.id).padStart(4,'0')} ${i.head} ${i.mask} ${i.color}`.toLowerCase().includes(query)&&(!activeTrait||[i.head,i.mask,i.color].includes(activeTrait)));list.sort((a,b)=>sort==='price-high'?b.price-a.price:sort==='id'?a.id-b.id:a.price-b.price);document.querySelector('#results').innerHTML=list.map(card).join('')||'<div class="empty" style="grid-column:1/-1"><h3>No matching identities.</h3><p>Try another ID or trait.</p><button class="text-button" id="reset-search">Reset filters</button></div>';document.querySelector('#result-count').textContent=`${list.length} preview ${list.length===1?'item':'items'} · 3,333 planned`;}
function showItem(id){const item=items.find(i=>i.id===Number(id));if(!item)return;document.querySelector('#nft-detail').innerHTML=`<div class="eyebrow">ZC / CONCEPT COLLECTIBLE</div>${art(item.art,'detail-art')}<h2 id="nft-title">Zc #${String(item.id).padStart(4,'0')}</h2><div class="detail-traits"><span>${item.head}</span><span>${item.mask}</span><span>${item.color}</span></div><div class="section-heading"><span>Example asking price</span><strong class="price">${money(item.price)} ZEC</strong></div><div class="demo-notice">This is a concept item. Buying, bidding and listing will open after the collection and trading service are connected.</div><button class="button wallet-trigger">${connection?'View connected wallet':'Connect Noir'} ↗</button>`;document.querySelector('#nft-dialog').showModal();}
function walletUI(value){connection=value;const address=value?.shielded||value?.accounts?.[0]?.addresses?.shielded;document.querySelectorAll('.header .wallet-trigger').forEach(b=>b.textContent=address?`${address.slice(0,6)}…${address.slice(-4)}`:'Sign in ↗');document.querySelector('#disconnect').hidden=!address;document.querySelector('#connect-noir').textContent=address?'Choose accounts ↗':'Connect Noir ↗';}
function openWallet(){document.querySelector('#nft-dialog').close();document.querySelector('#wallet-status').textContent=connection?'Your Noir wallet is connected. Live trading is not open.':'';document.querySelector('#wallet-dialog').showModal();}
document.addEventListener('click',e=>{if(e.target.closest('.wallet-trigger'))openWallet();if(e.target.closest('.close'))e.target.closest('dialog').close();const item=e.target.closest('[data-item]');if(item)showItem(item.dataset.item);const trait=e.target.closest('[data-trait]');if(trait){activeTrait=trait.dataset.trait;location.hash='/explorer';}if(e.target.closest('#clear-trait')||e.target.closest('#reset-search')){activeTrait='';search='';if(document.querySelector('#search'))document.querySelector('#search').value='';if(e.target.closest('#clear-trait'))render();else filterItems();}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;filterItems();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;filterItems();}if(e.target.id==='event-filter'){document.querySelectorAll('tbody tr').forEach(row=>row.hidden=e.target.value!=='all'&&row.querySelector('.event-type').textContent!==e.target.value);}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
document.querySelector('#connect-noir').addEventListener('click',async()=>{const button=document.querySelector('#connect-noir'),status=document.querySelector('#wallet-status');button.disabled=true;status.textContent='Waiting for approval in Noir…';try{const value=await connectNoir();walletUI(value);status.textContent='Wallet connected. Live trading is not open yet.';}catch(error){status.textContent=error.message||'Connection could not be completed. Please try again.';}finally{button.disabled=false;}});
document.querySelector('#disconnect').addEventListener('click',async()=>{try{await disconnectNoir();walletUI(null);document.querySelector('#wallet-status').textContent='Wallet disconnected.';}catch{document.querySelector('#wallet-status').textContent='Could not disconnect. Revoke this site in Noir settings.';}});
window.addEventListener('hashchange',()=>{if(!location.hash.includes('explorer'))activeTrait='';render();});
render();
restoreNoir().then(walletUI).catch(()=>walletUI(null));observeNoir(()=>restoreNoir().then(walletUI).catch(()=>walletUI(null)));
